mapper.update:
update mcp_tool_binding
set gateway_id = #{gatewayId},
    tool_id = #{toolId},
    bind_type = #{bindType},
    bind_target_id = #{bindTargetId},
    enabled = #{enabled},
    updated_at = #{updatedAt}
where id = #{id}
  and org_id = #{orgId}

mapper.delete:
delete from mcp_tool_binding
where id = #{id}
  and org_id = #{orgId}

delete from mcp_tool_binding
where tool_id = #{toolId}
  and org_id = #{orgId}
